<div class="ami-panel"><div class="ami-panel-body"><h2 class="ami-section-title">Preview Import Prodi</h2><p>Preview berlaku 30 menit. Unduhan CSV tidak mengonsumsi preview; hanya konfirmasi import yang mengonsumsinya.</p><div class="alert alert-info">Total baris: <?php echo html_escape((string) $total); ?>. Prodi: <?php echo html_escape((string) count($prodi)); ?>. Error: <?php echo html_escape((string) count($errors)); ?>.</div><?php if ($errors): ?><div class="alert alert-danger"><ul><?php foreach ($errors as $error): ?><li><?php echo html_escape($error['sheet']); ?> baris <?php echo html_escape((string) $error['row']); ?>: <?php echo html_escape($error['message']); ?></li><?php endforeach; ?></ul></div><?php endif; ?><h3>Program Studi</h3><div class="table-responsive"><table class="table ami-table"><thead><tr><th>Baris</th><th>Kode</th><th>Nama</th><th>Jenjang</th><th>Klasifikasi</th></tr></thead><tbody><?php foreach ($prodi as $row): ?><tr><td><?php echo html_escape((string) ($row['row_number'] ?? '')); ?></td><td><?php echo html_escape($row['kode_prodi']); ?></td><td><?php echo html_escape($row['nama_prodi']); ?></td><td><?php echo html_escape($row['jenjang']); ?></td><td><span class="badge badge-<?php echo ($row['classification'] ?? '') === 'update' ? 'warning' : 'success'; ?>"><?php echo html_escape($classification_labels[$row['classification'] ?? ''] ?? $row['classification'] ?? ''); ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php if ($token): ?><?php echo form_open('lpmpi/prodi-import/confirm', ['class' => 'd-inline']); ?><input type="hidden" name="token" value="<?php echo html_escape($token); ?>"><button class="btn-ami btn-primary" type="submit">Konfirmasi Import</button><?php echo form_close(); ?><?php endif; ?><?php echo form_open('lpmpi/prodi-import/cancel', ['class' => 'd-inline']); ?><button class="btn-ami btn-outline-ami" type="submit">Batal</button><?php echo form_close(); ?></div></div><?php include APPPATH . 'views/layouts/footer.php'; ?>
